function aitoHtml(text) {
    text = text.replace(/<think>[\s\S]+?<\/think>/,'');    
    if(!text)return "正在分析中......";    
    let lines = text.split(/<br>|\n/).filter(line => line.trim() !== '');
    let html = '';
    let currentListType = null;
    let inTable = false;
    let tableContent = '';
    let inBlock = false;
    let blockType = '';
    let blockContent = '';
    for(let i=0;i<lines.length;i++){
        let line = lines[i];
        let content="";
        if(!line)continue;
        if(line.startsWith('## ')){
            content = line.replace(/^## /g,'');
            content = `<h3 class="ai-h3">${content}</h2>`;
            html += content
        }
        else if(line.startsWith('### ')){
            content = line.replace(/^### /g,'');
            content = `<h3 class="ai-h3">${content}</h3>`;
            html += content
        }
        else if(line.startsWith('#### ')){
            content = line.replace(/^#### /g,'');
            content = `<h4 class="ai-h4">${content}</h4>`;
            html += content
        }
       else if(/^(?:\s*- |● )/.test(line)){
        	    content = line.replace(/^\s*- |^● /g,''); 	    
        	    content = `<li class="ai-list">${content}</li>`;                         
            html += content
        }
        else if(/^\s*\|.*\|\s*$/.test(line) && !inTable){
        	    inTable = true;
        	    tableContent += line +"\n";
         }
         else if(inTable){
             if (line.match(/^\s*\|.*\|\s*$/)) {
                tableContent += line + '\n';
            } else {
                html += processTable(tableContent.trim());
                inTable = false;
                tableContent = '';
                i--;
            }
            continue;
         }

         else if(/^\d+\./.test(line)){
             content = `<p class="ai-listp">${line}</p>`;
             html += content
         }
         else{
                content = line.replace(/^> /g,'');
         	   content = `<p class="ai-content">${content}</p>`;
                html += content
         	}

    }

html = `<div id="ai-body">${inlineFormat(html)}</div>`
return html
}


function processTable(content) {
    const rows = content.split('\n').filter(row => row.trim());
    if (rows.length < 2) return `<pre>${content}</pre>`;

    let tableHTML = '<table class="data-table">';

    rows.forEach((row, index) => {
        if (row.match(/^\s*\|[-:\|]+\|\s*$/)) return;       
        const cells = row.split('|').filter(cell => cell.trim() !== '');
        if (cells.length === 0) return;       
        if (index === 0) {          
            tableHTML += '<thead class="ai-thead"><tr class="ai-tr">';
            cells.forEach(cell => {
                tableHTML += `<th class="ai-th">${inlineFormat(cell.trim())}</th>`;
            });
            tableHTML += '</tr></thead><tbody class="ai-tbody">';
        } else {
            // 表体
            tableHTML += '<tr class="ai-tbody-tr">';
            cells.forEach(cell => {
                tableHTML += `<td class="ai-tbody-td">${inlineFormat(cell.trim())}</td>`;
            });
            tableHTML += '</tr>';
        }
    });

    tableHTML += '</tbody></table>';
    return tableHTML;
}

function inlineFormat(text) {

    let result = text.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

    result = result.replace(/```.*?```/g,'')
                 .replace(/<media-block>/g,'<div class="media-block"><div class="media-c">')
                 .replace(/<\/media-block>/g,'</div></div>')
                 .replace(/data-scheme=".*?mid=(\d+)[^"]+"/g,`onclick="openContent('$1')"`)
                 .replace(/<span class="(?:vator|nick|arrow)"[^>]*?>[^<]*?<\/span>/g,'')
                 .replace(/data-width=\d+ data-height=\d+/g,'')
    return result;
}

function formatTime(dateStr) {
    const date = new Date(dateStr);
    const year = date.getFullYear();
    const month = date.getMonth() + 1; 
    const day = date.getDate();
    const hours = date.getHours().toString().padStart(2, '0');
    const minutes = date.getMinutes().toString().padStart(2, '0');

    return `${year}年${month}月${day}日 ${hours}:${minutes}`;
}

function formatCount(count) {
  if (count < 10000) return count.toString();  
  const inWan = (count / 10000).toFixed(2);
  return inWan.endsWith('.00') 
    ? `${inWan.split('.')[0]}万` 
    : `${inWan}万`;
}

function getContent($) {
    let galleryItems = "",
        videos = "";
        let long_imgs  = $.pics!==undefined ? $.pics : [];
        let long_video = $.page_info?.type === "video" ? $.page_info : {};
    	if(long_imgs.length!==undefined) {
           galleryItems = long_imgs.map((img, i) =>{
               let type = "";
               if(img.type=="livephoto")type="live图";
               if(img.type=="video")type="视频";
               if(img.url.match(/gif$/))type="动图";
               let onclick = img.videoSrc ?`onclick="java.openVideoPlayer('${img.videoSrc}','视频',false)"`:"";
               type = type?`<div class="zoom-icon">${type}</div>`:"";

               let originalImg = img?.large?.url?img?.large?.url:"";
               originalImg = originalImg.replace(/(http.*?.sinaimg.cn\/).*?\//,'$1oslarge/');

               return `<div class="gallery-item" ${onclick}>
               <img src="${img.url}" data-original="${originalImg}" loading="lazy">
                ${type}
                </div>`
           }
         ).join('');
           galleryItems = `<div class="image-gallery">${galleryItems}</div>`;
        }
        if (JSON.stringify(long_video) !== "{}") {
             if (long_video.urls) {
                  long_video = long_video.urls;
                  videos = long_video.hevc_mp4_hd || long_video.mp4_720p_mp4 || long_video.mp4_hd_mp4 || long_video.mp4_ld_mp4
             } else {
             long_video = long_video.media_info;
             videos = long_video.stream_url_hd || long_video.stream_url 
        }
            videos = `<div class="media-container"><video src="${videos}" controls poster="${$.page_info.page_pic.url}"></video></div>`
        }
    let remarkName =  this.getU2S("users",$?.user?.id)?this.getU2S("users",$?.user?.id).remarkName:"";
    remarkName = remarkName || $?.user?.remark;
    return `
<div class="comment-item">
<div class="comment-user">
<img class="user-avatar" src="${$?.user?.avatar_hd}" onclick="openUser('${$?.user?.id}')">
<div class="user-info">
<span class="user-name" onclick="openUser('${$?.user?.id}')">${remarkName ||$?.user?.screen_name}<span class="remark">${remarkName?" @"+$?.user?.screen_name:""}</span></span>
<span class="comment-time">${formatTime($.created_at)}</span></div>
<div class="like_counts"><span>♡${formatCount($.attitudes_count)}</span></div>
</div>
<div class="comment-text">${$.text.replace(/https?:\/\/m.weibo.cn\/\d+\/(\d+)/g,'https://m.weibo.cn/a/$1').replace(/'\/n\//g,"'https://m.weibo.cn/n/")}</div>
${galleryItems}
${videos}

</div>`;

}

function liveUrl(href){
	const {java} = this
	  let res,id,url,body,stream_info,name;
  	id = href.match(/show\/(.*)/)[1];            
	  url = "http://weibo.com/l/pc/anchor/live?live_id="+id;
	  res = java.connect(url);
	  body = JSON.parse(String(res.body()));
	  if(body.error_code===27401)java.toast("直播不存在");
	  if(body.error_code===0){
			stream_info = body.data.item.stream_info;
			if(body.data.item.status === 5)java.toast("当前博主可能未开播");
			href = stream_info.replay_url ? stream_info.replay_url.origin : stream_info.pull.live_origin_hls_url;
			name = body.data.item.desc
   }

return {
	"url":href,
	"name":name
	}

}

function replaceLink(str){
	const {java} = this;
	let linkstyle = 'style="color:#1E88E5"';
	   return String(str)
//用户链接

.replace(/href=['"][^"]+?weibo.(?:com|cn)\/(u|profile)\/(\d+)['"]/g,`onclick='openUser("$1")' ${linkstyle}`)
.replace(/href=['"]([^'"]+?weibo.(?:com|cn)\/n\/[^"']+)['"]/g,`onclick='openUser("$1")' ${linkstyle}`)

//话题链接

.replace(/href=['"][^"']+?(?:containerid=(?:231522|100103)type%3D1|s.weibo.com\/weibo\?q=)[^"']+?%23(.*?)%23[^'"]*?['"]/g, 
    function(match, p1) {

        if(match.includes('ai.s.weibo.com/api') || match.includes('m.s.weibo.com/applink')) {
            return match;
        }


        let decoded = decodeURIComponent(p1);   
        return `onclick='openUser("#${decoded}#")' ${linkstyle}`;
    }
)

//正文链接
.replace(/href=['"][^'"]*?(?:m\.weibo\.cn|weibo\.com)*\/(?:\d+\/\d+|a|status|detail\/\d+|(?:\d+|status)\/[a-zA-Z\d]{9,18})[^'"]*?['"]/g,function(match, p1) {

   var match1 = match.match(/\/(\d+)\??"$/);
		var match2 = match.match(/(?:\d+|status)\/([a-zA-Z\d]{9,13})\??/);
        var id = match1 ? match1[1] : (match2 ? match2[1] : "");
        if(id == "" || match.includes('ai.s.weibo.com/api') || match.includes('m.s.weibo.com/applink')){
        	   return match
        	}
        return `onclick='openContent("${id}")' ${linkstyle}`;
    })

//超话链接
.replace(/href=['"][^'"]+?(?:containerid=|\/p\/)([\da-z]{30,60})[^'"]*?['"]/g,`onclick='openUser("$1")' ${linkstyle}`);

}


