                feedback.textContent = '订阅失败';
                feedback.style.color = '#F44336';
                setTimeout(() => feedback.textContent = '', 2000);
            }
        }

        function handleJump() {
            window.open("${url}");
        }

        function handleShare() {          
            java.open("sort",${/^http/.test(openUrl)?'"'+openUrl+'"':'JSON.stringify('+openUrl+')'},"${name}")
        }

        function handleCopy(){
            let url;
            switch("${t}"){
                case "users":
                     url = "${name}::https://m.weibo.cn/api/container/getIndex?containerid=107603${id}_-_WEIBO_SECOND_PROFILE_WEIBO&page_type=03&page={\\{page}}";
                break;
                case "topics":
                    url = "${name}::https://m.weibo.cn/api/container/getIndex?containerid=231522type%3D1%26t%3D10%26q%3D${encodeURIComponent("#"+id+"#")}&isnewpage=1&luicode=10000011&lfid=100103type%3D38%26q%3D${encodeURIComponent(id)}%26t%3D&page={\{page}}"
                break;
                case "superTopics":
                    url = "${name}::https://m.weibo.cn/api/container/getIndex?containerid=${id}_-_feed&page={\{page}}"
                break;
            }
            copyText(url)
        }

        function copyText(text) {
            if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(text).then(() => {
                    java.toast("复制成功\\n"+text)
                }).catch(err => {
                    console.error('复制失败:', err);
                    fallbackCopy(text);
                 });
             } else {fallbackCopy(text);}
          }
          function fallbackCopy(text) {
              const textarea = document.createElement('textarea');
              textarea.value = text;
              textarea.style.position = 'fixed';
              textarea.style.opacity = '0';
              document.body.appendChild(textarea);
              textarea.select();
              try {
                  const successful = document.execCommand('copy');
                  if (successful) {console.log('复制成功（fallback）:', text);
                   } else {console.error('复制失败（fallback）');}
                   } catch (err) {console.error('复制异常:', err);}
                   document.body.removeChild(textarea);
              }


    </script>
    `;

	}

