            if (setTagValue){
                let tempTextArea = document.createElement('textarea');
                tempTextArea.value = setTagValue;
                document.body.appendChild(tempTextArea);
                tempTextArea.select();
                document.execCommand('copy');
                document.body.removeChild(tempTextArea);
                alert('内容已复制到剪贴板: ' + setTagValue);
            } else {
                alert('localStorage中没有找到setTag的值');
            }
}

function editTag(){
    let dialog = createModalDialog();
    let text = localStorage.getItem('setTag');
    const tagsWrapper = document.createElement('div');
    tagsWrapper.style.cssText = `
        margin: 5px;
        padding:5px;
        max-height:50vh;
        overflow-y: auto;
        display: flex;
        flex-wrap: wrap;
        align-items: flex-start;
    `;        
    const urls = text.split('#');
    const buttonData = urls.filter(part => part.trim() !== '');        
    buttonData.forEach((data, index) => {
        const [label, url] = data.split('@');
        const button = document.createElement('input');
        button.type = "text";
        button.value = label || `标签${index + 1}`;
        button.style.cssText = `
            padding: 5px 5px;
            border-radius: 5px;
            white-space: wrap;
            flex-shrink: 0;
            background-color: #2196F3;
