            min-width: 60px;
            max-width: 100%;
            width:40%;
            margin-right: 10px;
            margin-bottom: 10px;
        `;

        button.dataset.id = url;   
        tagsWrapper.appendChild(button); 
    });            
        dialog.dialog.prepend(tagsWrapper);

        const promptText = document.createElement('p');
        promptText.textContent = '修改标签名或者删除相应文字，点击保存';
