            localStorage.setItem("setTag",saveTag);
            try{
            source.put("saveTag",saveTag);
            cache.put("saveTag",saveTag,0);
            cache.put("exploreM",exploreM,0)
            }catch(e){}
            alert("已更新标签");
            document.body.removeChild(dialog.overlay);

        });        

        dialog.dialog.appendChild(copyButton);          
}



