function gengxin(){
const {java, source} = this;
	let url0='https://gitee.com/lyc486/yuedu2/commits/main/订阅/洛娅橙/lyc.json?browser_history=0&page=1&per=3';
	let rr0=java.get(url0,{'User-Agent': 'Mozilla/5.0 (Linux; Android 14)','X-Requested-With': 'XMLHttpRequest'}).body();
	let gxlrr = com.jayway.jsonpath.JsonPath.read(rr0, '$.list[0:3].title');
	let [gxlr, gxlr2, gxlr3] = gxlrr;
	let banben = String(source.sortUrl).match(/let banben="([\d\.]+)"/)[1];
	gxlr=String(gxlr).split(/^([^\-]+)-/);
	gxlr[0]=='' ? '' : gxlr=['','0',gxlr[0]];
	let gxts;
	if (gxlr[1]>banben){gxts=['更新','0,140,186'];}
	else {gxts= ['导入','76,175,80'];};
	let htm = `<html>
<head>
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<style>
table {
	text-align: center;
	margin: 0 auto;
	}
.ann {
	display: flex;
	justify-content: center;
	align-items: center;
	height: 50vh;
	}
button {
	background-color: rgb(${gxts[1]});
	color: white;
	border: none;
	border-radius: 4px;
	height: 6vh;
	width: 30vw;
	overflow: hidden;
	}
button span {
  cursor: pointer;
  display: inline-block;
  position: relative;
  transition: 0.4s;
}
button span:after {
  content: '>';
  position: absolute;
  opacity: 0;
  top: 0;
  right: 30px;
  transition: 0.2s;
}
button:active span {
  padding-right: 20px;
}
button:active span:after {
  opacity: 1;
  right: -40px;
}
</style>
</head>
<body>
<table border="1" cellspacing="0">
<th colspan="2">最新日志：${gxlr[2]}</th>
<tr>
<td>仓库版本：${gxlr[1]}</td>
<td>本地版本：${banben}</td>
</tr>
<tr>
<td colspan="2" style="text-align: left;">往期日志：${gxlr2}<br>　　　　　${gxlr3}</td>
</tr>
</table>
<div class="ann">
<a href="legado://import/importonline?src=https://gitee.com/lyc486/yuedu2/raw/main/订阅/洛娅橙/lyc.json">
<button><span>${gxts[0]}</span></button>
</a>
</div>
<p style="font-size: 16px;">导入订阅源窗口需手动选中，然后确认</p>
<a href="legado://import/importonline?src=https://cdn.jsdelivr.net/gh/Luoyacheng/yuedu@main/订阅/洛娅橙/lyc.json" style="font-size: 10px;">备用链接</a>
</body>
</html>`;
if(gxts[0]=='更新') {
java.startBrowser(`data:text/html;base64,${java.base64Encode(htm)}`,'订阅源更新');return false;}
return true;
}

