        padding: 10px 18px;
        margin: 12px 0 8px;
    }
    .next-chapter-btn {
        width: 85%;
        padding: 12px 20px;
        font-size: 15px;
        margin: 20px auto;
    }
    #detail-page .tab-btn {
        padding: 10px 20px;
        font-size: 15px;
    }
    #detail-page .comments-container {
        padding: 15px;
    }
    #detail-page .start-reading-btn {
        padding: 10px 20px;
        font-size: 15px;
        margin: 10px 0 15px;
    }
    #detail-button {
        width: 42px;
        height: 42px;
        top: 12px;
        right: 12px;
    }
    #detail-button .hamburger {
        width: 20px;
        height: 16px;
    }
    #detail-button .hamburger span {
        width: 20px;
        height: 2.5px;
    }
    #detail-button.is-detail .hamburger span:nth-child(1) {
        transform: translateY(6.5px) rotate(45deg);
    }
    #detail-button.is-detail .hamburger span:nth-child(3) {
        transform: translateY(-6.5px) rotate(-45deg);
    }
    #comment-button {
        width: 42px;
        height: 42px;
        top: 64px;
        right: 12px;
        font-size: 18px;
    }
    #auto-scroll-button {
        width: 50px;
        height: 50px;
        bottom: 90px;
        right: 15px;
        font-size: 20px;
    }
}
@media (max-width: 480px) {
    #detail-page {
        padding: 10px;
    }
    #detail-page .cover-container {
        flex: 0 0 200px;
    }
    #detail-page .chapters-list {
        grid-template-columns: repeat(auto-fill, minmax(85px, 1fr));
        max-height: 350px;
    }
    #detail-page .chapter-item {
        padding: 8px;
        min-height: 55px;
    }
    #detail-page .chapter-number {
        font-size: 13px;
    }
