    #detail-page .start-reading-btn {
        padding: 8px 16px;
        font-size: 14px;
        margin: 8px 0 12px;
    }
    #detail-button {
        width: 40px;
        height: 40px;
        top: 10px;
        right: 10px;
    }
    #detail-button .hamburger {
        width: 18px;
        height: 14px;
    }
    #detail-button .hamburger span {
        width: 18px;
        height: 2.2px;
    }
    #detail-button.is-detail .hamburger span:nth-child(1) {
        transform: translateY(6px) rotate(45deg);
    }
    #detail-button.is-detail .hamburger span:nth-child(3) {
        transform: translateY(-6px) rotate(-45deg);
    }
    #comment-button {
        width: 40px;
        height: 40px;
        top: 60px;
        right: 10px;
        font-size: 16px;
    }
    #auto-scroll-button {
        width: 48px;
        height: 48px;
        bottom: 85px;
        right: 12px;
        font-size: 18px;
    }
}

